const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.'.split(''))

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdentChar = (c) => isLetter(c) || isDigit(c) || c === '_'
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

function fail(line, col, message) {
  const e = new Error(message)
  e.scanError = true
  e.line = line
  e.col = col
  throw e
}

export function scan(text) {
  const s = Array.from(text)
  const n = s.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const advance = () => {
    const c = s[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = col - ((col - 1) % 4) + 4
    } else col++
    return c
  }

  // digits of one run, with single `_` between two digits
  const run = (ok) => {
    let j = i
    while (j < n && (ok(s[j]) || (s[j] === '_' && j > i && ok(s[j - 1]) && ok(s[j + 1])))) j++
    return j
  }

  while (i < n) {
    const c = s[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance()
      continue
    }
    const sl = line
    const sc = col
    const push = (kind, body) => tokens.push({ line: sl, col: sc, kind, body })

    if (c === '/' && s[i + 1] === '/') {
      while (i < n && s[i] !== '\n') advance()
      continue
    }
    if (c === '/' && s[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) fail(sl, sc, 'unterminated block comment')
        if (s[i] === '/' && s[i + 1] === '*') {
          depth++
          advance()
          advance()
        } else if (s[i] === '*' && s[i + 1] === '/') {
          depth--
          advance()
          advance()
        } else advance()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && s[i + 1] === '"') {
      let j = i + 2
      while (j < n && s[j] !== '"') j++
      if (j >= n) fail(sl, sc, 'unterminated string')
      const val = s.slice(i + 2, j).join('')
      while (i <= j) advance()
      push('rawstring', JSON.stringify(val))
      continue
    }
    if (isLetter(c) || c === '_') {
      let j = i
      while (j < n && isIdentChar(s[j])) j++
      const word = s.slice(i, j).join('')
      while (i < j) advance()
      push(KEYWORDS.has(word) ? 'keyword' : 'ident', word)
      continue
    }
    if (isDigit(c)) {
      let j
      let bad = false
      const p = (s[i + 1] || '').toLowerCase()
      const pred = p === 'x' ? isHex : p === 'b' ? isBin : p === 'o' ? isOct : null
      if (c === '0' && pred) {
        if (pred(s[i + 2])) j = run2(i + 2, pred)
        else {
          j = i + 2
          bad = true
        }
      } else {
        j = run2(i, isDigit)
        if (s[j] === '.' && isDigit(s[j + 1])) j = run2(j + 1, isDigit)
        if (s[j] === 'e' || s[j] === 'E') {
          if (isDigit(s[j + 1])) j = run2(j + 1, isDigit)
          else if ((s[j + 1] === '+' || s[j + 1] === '-') && isDigit(s[j + 2])) j = run2(j + 2, isDigit)
        }
      }
      if (bad || isIdentChar(s[j])) {
        while (j < n && isIdentChar(s[j])) j++
        fail(sl, sc, `invalid number ${s.slice(i, j).join('')}`)
      }
      const body = s.slice(i, j).join('')
      while (i < j) advance()
      push('number', body)
      continue
    }
    if (c === '"') {
      advance()
      let val = ''
      for (;;) {
        if (i >= n) fail(sl, sc, 'unterminated string')
        const ch = s[i]
        if (ch === '\n') fail(line, col, 'newline in string')
        if (ch === '"') {
          advance()
          break
        }
        if (ch !== '\\') {
          val += ch
          advance()
          continue
        }
        const bl = line
        const bc = col
        advance()
        if (i >= n) fail(sl, sc, 'unterminated string')
        const e = s[i]
        const bad = () => fail(bl, bc, `invalid escape \\${e}`)
