          val += simple[e]
          advance()
        } else if (e === 'x') {
          if (!(isHex(s[i + 1]) && isHex(s[i + 2]))) bad()
          val += String.fromCodePoint(parseInt(s[i + 1] + s[i + 2], 16))
          advance()
          advance()
          advance()
