          val += String.fromCodePoint(hex.length ? parseInt(hex, 16) : 0)
          while (i <= j) advance()
        } else bad()
      }
      push('string', JSON.stringify(val))
      continue
    }
    const two = c + (s[i + 1] || '')
    if (PUNCT2.has(two)) {
      advance()
      advance()
      push('punct', two)
      continue
    }
    if (PUNCT1.has(c)) {
      advance()
      push('punct', c)
      continue
    }
    fail(sl, sc, `unexpected character ${c}`)
  }
  return tokens

  function run2(start, ok) {
    let j = start
    while (j < n && (ok(s[j]) || (s[j] === '_' && j > start && ok(s[j - 1]) && ok(s[j + 1])))) j++
    return j
  }
}
